CREATE TABLE exams (
    id                   UUID         NOT NULL DEFAULT gen_random_uuid(),
    course_id            UUID         NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
    title                VARCHAR(200) NOT NULL,
    pass_score           SMALLINT     NOT NULL DEFAULT 70,
    time_limit_minutes   SMALLINT,
    CONSTRAINT pk_exams PRIMARY KEY (id),
    CONSTRAINT uq_exams_course UNIQUE (course_id)
);

CREATE TABLE exam_questions (
    id             UUID NOT NULL DEFAULT gen_random_uuid(),
    exam_id        UUID NOT NULL REFERENCES exams(id) ON DELETE CASCADE,
    question_text  TEXT NOT NULL,
    order_index    SMALLINT NOT NULL,
    CONSTRAINT pk_exam_questions PRIMARY KEY (id)
);
CREATE INDEX idx_exam_questions_exam ON exam_questions (exam_id);

CREATE TABLE exam_choices (
    id           UUID    NOT NULL DEFAULT gen_random_uuid(),
    question_id  UUID    NOT NULL REFERENCES exam_questions(id) ON DELETE CASCADE,
    choice_text  TEXT    NOT NULL,
    is_correct   BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT pk_exam_choices PRIMARY KEY (id)
);
CREATE INDEX idx_exam_choices_question ON exam_choices (question_id);

CREATE TABLE exam_attempts (
    id        UUID        NOT NULL DEFAULT gen_random_uuid(),
    user_id   UUID        NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    exam_id   UUID        NOT NULL REFERENCES exams(id) ON DELETE CASCADE,
    score     SMALLINT    NOT NULL,
    passed    BOOLEAN     NOT NULL,
    taken_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT pk_exam_attempts PRIMARY KEY (id)
);
CREATE INDEX idx_exam_attempts_user ON exam_attempts (user_id, exam_id);

